using System;
using System.Threading.Tasks;

namespace Iryo.Billing;

public class FeeCalculator
{
	public int Calculate(int a, int b)
	{
		return a + b;
	}

	public long Calculate(long a, long b)
	{
		return a + b;
	}

	public double Calculate(double a, double b)
	{
		return a + b;
	}

	public int Calculate(int a, int b, int c)
	{
		return a + b + c;
	}

	public int Calculate(params int[] points)
	{
		int num = 0;
		foreach (int num2 in points)
		{
			num += num2;
		}
		if (points.Length > 3)
		{
			num = (int)((double)num * 0.9);
		}
		return num;
	}

	public string Run(Action task)
	{
		task();
		return "同期実行";
	}

	public string Run(Func<Task> task)
	{
		task().GetAwaiter().GetResult();
		return "非同期実行";
	}

	public int Scale(int value, int factor)
	{
		return value * factor;
	}

	public double Scale(int value, double factor)
	{
		return (double)value * factor;
	}

	public decimal Pay(decimal amount)
	{
		return amount;
	}
}
